INSERT INTO periodo(numero,nome,ordem) VALUES(3,'3º período',3) ON CONFLICT(numero) DO NOTHING;
INSERT INTO disciplina(periodo_id,nome,slug,descricao,possui_prova) SELECT id,'Design de Artefatos Digitais','design_de_artefatos_digitais','Fundamentos, interfaces, diagramação e Design Thinking, com oito aulas e material complementar da Matriz CSD.',FALSE FROM periodo WHERE numero=3 ON CONFLICT(slug) DO NOTHING;
INSERT INTO assunto(disciplina_id,nome,slug,ordem) SELECT id,'Introdução ao Design','introducao_ao_design',1 FROM disciplina WHERE slug='design_de_artefatos_digitais' ON CONFLICT(disciplina_id,slug) DO NOTHING;
INSERT INTO material(disciplina_id,assunto_id,titulo,descricao,tipo,referencia_externa,fonte_monitor_virtual) SELECT d.id,a.id,'Aula 1 — Introdução ao Design','PDF original conferido; fonte do Monitor Virtual.','SLIDE_AULA','local:materiais_academicos/periodo_03/design_de_artefatos_digitais/aula_01_introducao_ao_design/Aula 01 - Design de Artefatos Digitais.pdf',TRUE FROM disciplina d JOIN assunto a ON a.disciplina_id=d.id AND a.slug='introducao_ao_design' WHERE d.slug='design_de_artefatos_digitais' AND NOT EXISTS(SELECT 1 FROM material m WHERE m.disciplina_id=d.id AND m.referencia_externa='local:materiais_academicos/periodo_03/design_de_artefatos_digitais/aula_01_introducao_ao_design/Aula 01 - Design de Artefatos Digitais.pdf');
